// Register-row nodes, third batch: Grasshopper Vector / Plane components and the Sets data-tree path components
// (Tree Statistics, Construct Path, Deconstruct Path), added one Register row at a time.
// Every node has a hand-computed oracle in dino8-app/tests/sections/104_ghv*.sh (generated by tests/flowrows6_gen.py):
// the closed form is written next to the expected value there, never derived from this code. Angles are radians, like
// every other angle port of the Maths nodes (Sine, Pi, ...). Where a component description leaves a corner open, the
// choice made here is stated in the node's description text.
#include <algorithm>
#include <cctype>
#include <cmath>
#include <cstdlib>
#include <string>
#include <vector>

#include "flow/FlowGraph.h"

namespace dino8::flow {

namespace {

PortDef In(std::string name, Kind k, Access acc = Access::Item, Value def = Value::Null(), bool optional = false) {
  PortDef p; p.name = name; p.nick = name; p.kind = k; p.access = acc; p.def = std::move(def); p.optional = optional; return p;
}
PortDef Out(std::string name, Kind k) { PortDef p; p.name = name; p.nick = name; p.kind = k; return p; }

constexpr double kPi = 3.14159265358979323846;
constexpr double kTiny = 1e-12;

Vector3d UnitOf(const Vector3d& v) { Vector3d u = v; u.Unitize(); return u; }

void AddVectors3() {
  Registry& r = Registry::Get();
  struct Axis { const char* name; const char* nick; Vector3d dir; const char* what; };
  const Axis axes[] = {{"Unit X", "X", Vector3d(1, 0, 0), "X"}, {"Unit Y", "Y", Vector3d(0, 1, 0), "Y"}, {"Unit Z", "Z", Vector3d(0, 0, 1), "Z"}};
  for (const Axis& ax : axes) {
    NodeDef d; d.name = ax.name; d.nick = ax.nick; d.category = "Vector"; d.subcategory = "Vector";
    d.description = std::string("The unit vector along the world ") + ax.what + " axis, multiplied by Factor.";
    d.inputs = {In("Factor", Kind::Number, Access::Item, Value::Number(1))};
    d.outputs = {Out("Unit vector", Kind::Vector)};
    const Vector3d dir = ax.dir;
    d.eval = [dir](EvalContext& c) { c.Out(0, Value::Vector(dir * c.Num(0))); };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Deconstruct Vector"; d.nick = "DeVec"; d.category = "Vector"; d.subcategory = "Vector";
    d.description = "The X, Y and Z components of a vector.";
    d.inputs = {In("Vector", Kind::Vector, Access::Item, Value::Vector(Vector3d(0, 0, 0)))};
    d.outputs = {Out("X component", Kind::Number), Out("Y component", Kind::Number), Out("Z component", Kind::Number)};
    d.eval = [](EvalContext& c) {
      const Vector3d v = c.Vec(0, Vector3d(0, 0, 0));
      c.Out(0, Value::Number(v.x)); c.Out(1, Value::Number(v.y)); c.Out(2, Value::Number(v.z));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Vector Reverse"; d.nick = "Rev"; d.category = "Vector"; d.subcategory = "Vector";
    d.description = "The opposite vector: every component changes sign.";
    d.inputs = {In("Vector", Kind::Vector, Access::Item, Value::Vector(Vector3d(0, 0, 1)))};
    d.outputs = {Out("Reversed", Kind::Vector)};
    d.eval = [](EvalContext& c) { const Vector3d v = c.Vec(0); c.Out(0, Value::Vector(Vector3d(-v.x, -v.y, -v.z))); };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Angle"; d.nick = "Angle"; d.category = "Vector"; d.subcategory = "Vector";
    d.description = "The angle between two vectors in radians, in [0, pi] (0 when parallel, pi when opposite), and the reflex angle 2 pi minus it. A zero-length vector has no direction and is flagged.";
    d.inputs = {In("A", Kind::Vector, Access::Item, Value::Vector(Vector3d(1, 0, 0))), In("B", Kind::Vector, Access::Item, Value::Vector(Vector3d(0, 1, 0)))};
    d.outputs = {Out("Angle", Kind::Number), Out("Reflex", Kind::Number)};
    d.eval = [](EvalContext& c) {
      const Vector3d a = c.Vec(0), b = c.Vec(1);
      const double la = a.Length(), lb = b.Length();
      if (!(la > kTiny) || !(lb > kTiny)) { c.Fail("A zero-length vector has no direction"); return; }
      // atan2(|a x b|, a . b) stays accurate near 0 and pi, where acos of a rounded cosine would lose digits.
      const double ang = std::atan2(ON_CrossProduct(a, b).Length(), ON_DotProduct(a, b));
      c.Out(0, Value::Number(ang));
      c.Out(1, Value::Number(2.0 * kPi - ang));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Vector Rotate"; d.nick = "VRot"; d.category = "Vector"; d.subcategory = "Vector";
    d.description = "Rotates a vector about an axis by an angle in radians, counter-clockwise seen from the tip of the axis (right-hand rule). A zero-length axis is flagged.";
    d.inputs = {In("Vector", Kind::Vector, Access::Item, Value::Vector(Vector3d(1, 0, 0))), In("Axis", Kind::Vector, Access::Item, Value::Vector(Vector3d(0, 0, 1))),
                In("Angle", Kind::Number, Access::Item, Value::Number(kPi / 2))};
    d.outputs = {Out("Vector", Kind::Vector)};
    d.eval = [](EvalContext& c) {
      const Vector3d v = c.Vec(0);
      const Vector3d axis = c.Vec(1);
      if (!(axis.Length() > kTiny)) { c.Fail("A zero-length axis has no direction"); return; }
      const Vector3d k = UnitOf(axis);
      const double ang = c.Num(2), cs = std::cos(ang), sn = std::sin(ang);
      // Rodrigues: v cos + (k x v) sin + k (k . v)(1 - cos)
      const Vector3d out = v * cs + ON_CrossProduct(k, v) * sn + k * (ON_DotProduct(k, v) * (1.0 - cs));
      c.Out(0, Value::Vector(out));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Plane Offset"; d.nick = "PlOff"; d.category = "Vector"; d.subcategory = "Plane";
    d.description = "Moves a plane along its own normal by Distance (a negative distance moves it against the normal); the axes do not change. A plane with parallel axes is flagged.";
    d.inputs = {In("Plane", Kind::Plane, Access::Item, Value::PlaneV(Plane{})), In("Distance", Kind::Number, Access::Item, Value::Number(1))};
    d.outputs = {Out("Plane", Kind::Plane)};
    d.eval = [](EvalContext& c) {
      Plane p = c.PlaneIn(0);
      const Vector3d n = p.Normal();
      if (!(n.Length() > kTiny)) { c.Fail("The plane has parallel axes"); return; }
      p.origin = p.origin + UnitOf(n) * c.Num(1);
      c.Out(0, Value::PlaneV(p));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Plane Closest Point"; d.nick = "PlCP"; d.category = "Vector"; d.subcategory = "Plane";
    d.description = "The point of a plane nearest to a point (the foot of the perpendicular), and the signed distance of the point from the plane: positive on the side the normal points to. A plane with parallel axes is flagged.";
    d.inputs = {In("Plane", Kind::Plane, Access::Item, Value::PlaneV(Plane{})), In("Point", Kind::Point, Access::Item, Value::Point(Point3d(0, 0, 0)))};
    d.outputs = {Out("Closest Point", Kind::Point), Out("Distance", Kind::Number)};
    d.eval = [](EvalContext& c) {
      const Plane p = c.PlaneIn(0);
      const Vector3d nn = p.Normal();
      if (!(nn.Length() > kTiny)) { c.Fail("The plane has parallel axes"); return; }
      const Vector3d n = UnitOf(nn);
      const Point3d q = c.Pt(1);
      const double dist = ON_DotProduct(q - p.origin, n);
      c.Out(0, Value::Point(q - n * dist));
      c.Out(1, Value::Number(dist));
    };
    r.Add(d);
  }
}

// ---------------------------------------------------------------------------------------------------------------------
// Sets: data-tree paths
// ---------------------------------------------------------------------------------------------------------------------

// "{0;1;3}" -> 0 1 3. Spaces are allowed around the braces, the separators and the numbers; every index is a non-negative
// integer; at least one index is needed.
bool ParsePathText(const std::string& text, std::vector<int>& out) {
  out.clear();
  size_t a = 0, b = text.size();
  while (a < b && std::isspace(static_cast<unsigned char>(text[a]))) ++a;
  while (b > a && std::isspace(static_cast<unsigned char>(text[b - 1]))) --b;
  if (b - a < 3 || text[a] != '{' || text[b - 1] != '}') return false;
  ++a; --b;
  size_t i = a;
  while (i <= b) {
    size_t j = i;
    while (j < b && text[j] != ';') ++j;
    size_t s = i, e = j;
    while (s < e && std::isspace(static_cast<unsigned char>(text[s]))) ++s;
    while (e > s && std::isspace(static_cast<unsigned char>(text[e - 1]))) --e;
    if (s == e) return false;
    long long v = 0;
    for (size_t k = s; k < e; ++k) {
      if (!std::isdigit(static_cast<unsigned char>(text[k]))) return false;
      v = v * 10 + (text[k] - '0');
      if (v > 1000000000LL) return false;
    }
    out.push_back(static_cast<int>(v));
    i = j + 1;
  }
  return !out.empty();
}

void AddSets3() {
  Registry& r = Registry::Get();
  {
    NodeDef d; d.name = "Tree Statistics"; d.nick = "Stat"; d.category = "Sets"; d.subcategory = "Tree";
    d.description = "Describes a data tree: the path of every branch as text such as {0;1;3}, the number of items in each branch (in the same order) and the number of branches.";
    d.inputs = {In("Tree", Kind::Any, Access::Tree)};
    d.outputs = {Out("Path", Kind::Text), Out("Length", Kind::Integer), Out("Count", Kind::Integer)};
    d.eval = [](EvalContext& c) {
      const Tree* t = c.TreeIn(0);
      std::vector<Value> paths, lengths;
      if (t) {
        for (const Branch& b : t->branches) {
          paths.push_back(Value::Text(PathString(b.path)));
          lengths.push_back(Value::Integer(static_cast<long long>(b.items.size())));
        }
      }
      c.OutList(0, paths);
      c.OutList(1, lengths);
      c.Out(2, Value::Integer(static_cast<long long>(paths.size())));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Construct Path"; d.nick = "PathC"; d.category = "Sets"; d.subcategory = "Tree";
    d.description = "A path from its indices: the integers 0, 1, 3 give the text {0;1;3}. Indices must be non-negative and at least one is needed, otherwise the node is flagged.";
    d.inputs = {In("Indices", Kind::Integer, Access::List)};
    d.outputs = {Out("Path", Kind::Text)};
    d.eval = [](EvalContext& c) {
      const std::vector<Value>& l = c.List(0);
      if (l.empty()) { c.Fail("A path needs at least one index"); return; }
      std::vector<int> p;
      for (const Value& v : l) {
        double x;
        if (!v.AsNumber(x) || !std::isfinite(x) || x < 0 || x > 1e9) { c.Fail("A path index must be a non-negative integer"); return; }
        p.push_back(static_cast<int>(std::llround(x)));
      }
      c.Out(0, Value::Text(PathString(p)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Deconstruct Path"; d.nick = "PathD"; d.category = "Sets"; d.subcategory = "Tree";
    d.description = "The indices of a path written as text, {0;1;3} giving 0, 1, 3 and its length (the number of indices). Text that is not a path is flagged.";
    d.inputs = {In("Path", Kind::Text, Access::Item, Value::Text("{0}"))};
    d.outputs = {Out("Indices", Kind::Integer), Out("Length", Kind::Integer)};
    d.eval = [](EvalContext& c) {
      std::vector<int> p;
      if (!ParsePathText(c.Text(0), p)) { c.Fail("Not a path: expected indices between braces such as {0;1;3}"); return; }
      std::vector<Value> idx;
      for (int i : p) idx.push_back(Value::Integer(i));
      c.OutList(0, idx);
      c.Out(1, Value::Integer(static_cast<long long>(p.size())));
    };
    r.Add(d);
  }
}

}  // namespace

// Used by the Flatten Tree node of FlowNodesCore.cpp for its optional Path input.
bool ParseFlowPathText(const std::string& text, std::vector<int>& out) { return ParsePathText(text, out); }

void RegisterRowNodes3() {
  AddVectors3();
  AddSets3();
}

}  // namespace dino8::flow
